  action: "hover" | "definition" | "implementation" | "references" | "diagnostics" | "documentSymbol" | "workspaceSymbol" | "prepareCallHierarchy" | "incomingCalls" | "outgoingCalls";
  character?: number;
  file: string;
  includeDeclaration?: boolean;
  item_index?: number;
  language?: "arkts" | "cpp";
  line?: number;
  mode?: "debug" | "release";
  // Build target per module, for example {entry: phone, shared: default}. These are Hvigor targets, independent of the HDC device target.
  module_targets?: { [key: string]: string; };
  product?: string;
  project_path?: string;
  query?: string;
}): Promise<CallToolResult<{ data?: unknown; error?: { code: string; details?: unknown; message: string; retryable: boolean; }; ok: boolean; request_id: string; }>>; };
